//refAssemblies: System.Diagnostics.Process.dll, System.Text.Json.dll, TCAdmin.Monitor.SDK.dll, Microsoft.Win32.Registry.dll, System.Security.Principal.Windows.dll
using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Prepares the world before every start. The dedicated server cannot create a world: it loads
// SaveData/Worlds/<world name>~<World GUID> and its newest World~<n>.json, and stops at "Unable to get ApplicationVersion"
// without one. This script
//  - keeps the game's save folder (AppData/LocalLow/Vector3 Studio/Sunkenland of the user the server runs as) in the
//    service root as SaveData, so the file manager and backups see the worlds,
//  - renames the world folder when the world name was changed (the name is the server name in the session list),
//  - copies the world settings the panel keeps in Config/WorldSetting.json into the world folder,
//  - starts a new world (an empty World~0.json of the installed game version) when the folder has no save yet.
const string DefaultWorldName = "Sunkenland";
const string DefaultWorldGuid = "5a1c7e3d-2b9f-4c61-8e0a-7d3f9b1c2e45";

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');
var saveData = Path.Combine(root, "SaveData");
var worlds = Path.Combine(saveData, "Worlds");
var settingsFile = Path.Combine(root, "Config", "WorldSetting.json");
var linux = System.OperatingSystem.IsLinux();

// This script runs as the monitor (root on Linux) in a folder the customer can change over FTP/SFTP. A symbolic link
// (or junction) anywhere from the service root down to a path the script reads or writes would point it at a file
// outside the service, so the script stops instead of following one.
void NoLink(string path)
{
    var cmp = linux ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
    var full = Path.GetFullPath(path).TrimEnd('/', '\\');
    if (!full.StartsWith(root + Path.DirectorySeparatorChar, cmp)) throw new Exception(path + " is outside the service folder.");
    for (var p = full; p != null && p.Length > root.Length; p = Path.GetDirectoryName(p))
        if (new FileInfo(p).LinkTarget != null)
            throw new Exception(p.Substring(root.Length).TrimStart('/', '\\') + " is a symbolic link. Replace it with a normal file or folder and start the server again.");
}

// The world name: the ServerName key of the panel's world settings.
var worldName = DefaultWorldName;
string settings = null;
NoLink(settingsFile);
if (File.Exists(settingsFile))
{
    settings = File.ReadAllText(settingsFile);
    try
    {
        using (var json = JsonDocument.Parse(settings))
            if (json.RootElement.TryGetProperty("ServerName", out var serverName) && serverName.TryGetProperty("value", out var value)
                && !string.IsNullOrWhiteSpace(value.GetString()))
                worldName = value.GetString().Trim();
    }
    catch (JsonException ex)
    {
        throw new Exception("Config/WorldSetting.json is not valid JSON (" + ex.Message + "). Remove double quotes from the server name and the description (Config Files > World settings).");
    }
}
if (worldName.IndexOfAny(new[] { '~', '/', '\\', ':', '*', '?', '"', '<', '>', '|' }) >= 0 || worldName.EndsWith(".")
    || worldName.Any(char.IsControl) || worldName.Length > 100)
    throw new Exception("The server name '" + worldName + "' cannot be used as a folder name. Use at most 100 characters and remove ~ / \\ : * ? \" < > | from it (Config Files > World settings).");

// The world GUID the server is started with (-worldGuid of the command line).
var guidText = DefaultWorldGuid;
var argument = Regex.Match(Convert.ToString(ThisService.Commandline) ?? "", "-worldGuid\\s+\"?([^\\s\"]+)", RegexOptions.IgnoreCase);
if (argument.Success) guidText = argument.Groups[1].Value;
if (!Guid.TryParse(guidText, out var guid))
    throw new Exception("The World GUID '" + guidText + "' is not a GUID (Command Lines). It is the part after ~ in the world folder name.");
// The server compares the folder name with the lower-case GUID.
var id = guid.ToString();

void Own(string path)
{
    if (linux)
    {
        // No shell: the path holds the customer's world name. -R never follows a symbolic link (-P), -h covers the top.
        Chown("-R", "-h", "--reference=" + root, "--", path);
        return;
    }
    if (Directory.Exists(path)) Globals.OperatingSystem.SetDirectoryOwnerAutoDetect(path, true);
    else Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

void Ensure(string dir)
{
    if (Directory.Exists(dir)) return;
    var parent = Path.GetDirectoryName(dir);
    if (!Directory.Exists(parent)) Ensure(parent);
    Directory.CreateDirectory(dir);
    Own(dir);
}

NoLink(worlds);
Ensure(worlds);
if (linux) { NoLink(Path.Combine(root, "Logs")); Ensure(Path.Combine(root, "Logs")); } // the -logFile folder

// The game's save folder -> SaveData in the service root.
if (linux)
{
    // Wine keeps the Windows profile of the user that runs the server under drive_c/users/<user>.
    var users = Path.Combine(root, ".wine", "drive_c", "users");
    if (Directory.Exists(users))
    {
        foreach (var profile in Directory.GetDirectories(users).Where(d => Path.GetFileName(d) != "Public"))
        {
            var company = Path.Combine(profile, "AppData", "LocalLow", "Vector3 Studio");
            var link = Path.Combine(company, "Sunkenland");
            var info = new DirectoryInfo(link);
            if (info.LinkTarget == saveData) continue;
            NoLink(company); // the link itself is replaced below, the folders above it must be real
            if (!Directory.Exists(company))
            {
                Directory.CreateDirectory(company);
                Chown("-h", "--reference=" + profile, "--", company);
            }
            if (info.Exists && info.LinkTarget == null)
            {
                // Saves the server wrote before the folder was linked: keep them.
                Merge(link, saveData, false);
                Directory.Delete(link, true);
            }
            else if (info.Exists || info.LinkTarget != null) info.Delete();
            Directory.CreateSymbolicLink(link, saveData);
            Chown("-h", "--reference=" + profile, "--", link);
            ScriptConsole.WriteLine((object)("Linked the game's save folder to SaveData (" + Path.GetFileName(profile) + ")."));
        }
    }
}
else
{
    // Windows: the Windows profile of the service's own user (the blueprint runs every service as its own user, so two
    // servers never share the folder). A user that never ran anything has no profile yet: create it, the panel loads
    // it when it starts the server.
    var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
    var accountName = string.IsNullOrEmpty(credential.Domain) ? credential.UserName : credential.Domain + "\\" + credential.UserName;
    var sid = ((System.Security.Principal.SecurityIdentifier)new System.Security.Principal.NTAccount(accountName)
        .Translate(typeof(System.Security.Principal.SecurityIdentifier))).Value;
    var profile = ProfilePath(sid);
    if (profile == null || !Directory.Exists(profile))
    {
        var created = new StringBuilder(260);
        var result = UserProfiles.CreateProfile(sid, credential.UserName, created, (uint)created.Capacity);
        if (result != 0 && result != unchecked((int)0x800700B7))
            throw new Exception("Could not create the Windows profile of " + accountName + " (0x" + result.ToString("X8") + ").");
        profile = ProfilePath(sid) ?? created.ToString();
        ScriptConsole.WriteLine((object)("Created the Windows profile of " + accountName + ": " + profile));
    }
    var company = Path.Combine(profile, "AppData", "LocalLow", "Vector3 Studio");
    var link = Path.Combine(company, "Sunkenland");
    var info = new DirectoryInfo(link);
    var pointsHere = info.Exists && info.LinkTarget != null
        && string.Equals(Path.GetFullPath(info.LinkTarget).TrimEnd('\\'), saveData, StringComparison.OrdinalIgnoreCase);
    if (!pointsHere)
    {
        Directory.CreateDirectory(company);
        if (info.Exists && info.LinkTarget == null)
        {
            // Saves the server wrote before the folder was linked: keep them.
            Merge(link, saveData, false);
            Directory.Delete(link, true);
        }
        else if (info.LinkTarget != null) Directory.Delete(link);
        // A directory junction needs no privilege and works for the service user (the junction inherits the
        // profile's permissions; SaveData is the service user's folder).
        using (var mklink = Process.Start(new ProcessStartInfo("cmd.exe", "/c mklink /J \"" + link + "\" \"" + saveData + "\"")
               { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false, CreateNoWindow = true }))
        {
            var error = mklink.StandardError.ReadToEnd();
            mklink.StandardOutput.ReadToEnd();
            mklink.WaitForExit();
            if (mklink.ExitCode != 0) throw new Exception("Could not link " + link + " to SaveData: " + error.Trim());
        }
        ScriptConsole.WriteLine((object)("Linked the game's save folder (" + link + ") to SaveData."));
    }
}

// Windows: the panel reads the server's output from its console and keeps a copy in .tca/console.log, which it
// clears at every start. Keep the last 10 runs as Logs/server_<date>.log for the log viewer.
if (!linux)
{
    var consoleCopy = Path.Combine(root, ".tca", "console.log");
    NoLink(consoleCopy);
    if (File.Exists(consoleCopy) && new FileInfo(consoleCopy).Length > 0)
    {
        var logs = Path.Combine(root, "Logs");
        NoLink(logs);
        Ensure(logs);
        var archived = Path.Combine(logs, "server_" + File.GetLastWriteTime(consoleCopy).ToString("yyyy-MM-dd_HH-mm-ss") + ".log");
        NoLink(archived);
        if (!File.Exists(archived))
        {
            string raw;
            using (var stream = new FileStream(consoleCopy, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
            using (var reader = new StreamReader(stream, Encoding.UTF8)) raw = reader.ReadToEnd();
            // Without the console colour codes.
            File.WriteAllText(archived, Regex.Replace(raw, "\u001b\\[[0-9;?]*[A-Za-z]", ""), new UTF8Encoding(false));
            Own(archived);
        }
        foreach (var old in Directory.GetFiles(logs, "server_*.log").OrderByDescending(f => f, StringComparer.Ordinal).Skip(10)) File.Delete(old);
    }
}

// The world folder: <world name>~<GUID>. A folder of the same world under another name (the name was changed, or a
// world was uploaded with its own name) is merged into it.
var target = Path.Combine(worlds, worldName + "~" + id);
foreach (var other in Directory.GetDirectories(worlds))
{
    var folder = Path.GetFileName(other);
    var separator = folder.LastIndexOf('~');
    if (separator < 0 || !Guid.TryParse(folder.Substring(separator + 1), out var otherGuid) || otherGuid != guid) continue;
    if (string.Equals(other, target, StringComparison.Ordinal)) continue;
    NoLink(other);
    NoLink(target);
    if (!Directory.Exists(target))
    {
        Directory.Move(other, target);
        ScriptConsole.WriteLine((object)("Renamed the world folder '" + folder + "' to '" + Path.GetFileName(target) + "'."));
        continue;
    }
    Merge(other, target, true);
    Directory.Delete(other, true);
    ScriptConsole.WriteLine((object)("Moved the world '" + folder + "' to '" + Path.GetFileName(target) + "'."));
}
NoLink(target);
Ensure(target);

if (settings != null)
{
    var worldSettings = Path.Combine(target, "WorldSetting.json");
    NoLink(worldSettings);
    if (!File.Exists(worldSettings) || File.ReadAllText(worldSettings) != settings)
    {
        File.WriteAllText(worldSettings, settings, new UTF8Encoding(false));
        Own(worldSettings);
    }
}

if (!Directory.GetFiles(target, "World~*.json").Any(f => Regex.IsMatch(Path.GetFileName(f), "^World~[0-9]+\\.json$")))
{
    var version = GameVersion();
    if (version == null) throw new Exception("Could not read the version of the installed server from Sunkenland-DedicatedServer_Data/globalgamemanagers.");
    var save = Path.Combine(target, "World~0.json");
    NoLink(save);
    File.WriteAllText(save, "{\n\t\"ApplicationVersion\" : {\n\t\t\"__type\" : \"string\",\n\t\t\"value\" : \"" + version + "\"\n\t}\n}\n", new UTF8Encoding(false));
    Own(save);
    ScriptConsole.WriteLine((object)("Started a new world '" + worldName + "' (" + id + ", game version " + version + ")."));
}

// Merges a folder into another: anything keeps the newer file (WorldSetting.json is replaced from Config/ anyway).
// A linked folder inside is refused (following it would move files from outside the service folder into it); a linked
// file is moved as the link itself.
void Merge(string from, string to, bool keepPanelFiles)
{
    if (new DirectoryInfo(from).LinkTarget != null || new DirectoryInfo(to).LinkTarget != null)
        throw new Exception("Cannot merge " + from + " into " + to + ": one of them is a symbolic link. Replace it with a normal folder.");
    Directory.CreateDirectory(to);
    foreach (var dir in Directory.GetDirectories(from))
        Merge(dir, Path.Combine(to, Path.GetFileName(dir)), false);
    foreach (var file in Directory.GetFiles(from))
    {
        var dest = Path.Combine(to, Path.GetFileName(file));
        if (File.Exists(dest))
        {
            if (keepPanelFiles && string.Equals(Path.GetFileName(file), "WorldSetting.json", StringComparison.OrdinalIgnoreCase)) continue;
            if (File.GetLastWriteTimeUtc(dest) >= File.GetLastWriteTimeUtc(file)) continue;
            File.Delete(dest);
        }
        File.Move(file, dest);
    }
    Own(to);
}

// The game version (Application.version) is the only length-prefixed "x.y.z" string in globalgamemanagers.
string GameVersion()
{
    var file = Path.Combine(root, "Sunkenland-DedicatedServer_Data", "globalgamemanagers");
    if (!File.Exists(file)) return null;
    var text = Encoding.Latin1.GetString(File.ReadAllBytes(file));
    foreach (Match match in Regex.Matches(text, "([\\x03-\\x10])\\x00\\x00\\x00([0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,4})"))
        if (match.Groups[2].Value.Length == match.Groups[1].Value[0]) return match.Groups[2].Value;
    return null;
}

// chown without a shell (arguments are passed as they are).
void Chown(params string[] arguments)
{
    using (var process = Process.Start(new ProcessStartInfo("chown", arguments) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var error = process.StandardError.ReadToEndAsync();
        process.StandardOutput.ReadToEnd();
        process.WaitForExit();
        if (process.ExitCode != 0) ScriptConsole.WriteLine((object)("chown " + string.Join(" ", arguments) + ": " + error.Result.Trim()));
    }
}

string ProfilePath(string sid)
{
    using (var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\" + sid))
    {
        var path = key?.GetValue("ProfileImagePath") as string;
        return path == null ? null : Environment.ExpandEnvironmentVariables(path);
    }
}

static class UserProfiles
{
    [System.Runtime.InteropServices.DllImport("userenv.dll", CharSet = System.Runtime.InteropServices.CharSet.Unicode)]
    public static extern int CreateProfile(string sid, string userName, StringBuilder profilePath, uint length);
}

//refAssemblies: System.Net.NetworkInformation.dll, System.Net.Primitives.dll
using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The server has no save command and does not save when it is closed: the world is saved by its autosave only
// (every "Autosave interval" seconds, and only while players are online - the world is paused when it is empty).
// Before the panel stops the server this script lets a save that is being written finish, and when players are
// online it waits for the next autosave, so the last minutes of play are not lost.
const int DefaultInterval = 300;
const int MaxWaitSeconds = 330;

// The server log: the -logFile of the command line (Wine), else the copy of the console the panel keeps.
var logArgument = Regex.Match(Convert.ToString(ThisService.Commandline) ?? "", "-logFile\\s+\"?(?:Z:)?([^\"]+?)\"?(\\s+-|$)", RegexOptions.IgnoreCase);
var log = logArgument.Success ? logArgument.Groups[1].Value.Trim()
    : Path.Combine((string)ThisService.RootDirectory, ".tca", "console.log");
if (System.OperatingSystem.IsLinux()) log = log.Replace('\\', '/');
// This script runs as the monitor (root on Linux) and the command line can be the customer's: read only a file in the
// service folder with no symbolic link on the way (never a device or a file outside the service).
if (!InServiceFolder(log)) log = Path.Combine((string)ThisService.RootDirectory, System.OperatingSystem.IsLinux() ? "Logs/server.log" : ".tca/console.log");
if (!InServiceFolder(log))
{
    ScriptConsole.WriteLine((object)"The server log is a symbolic link or outside the service folder: not waiting for a save.");
    return;
}
int port = ThisService.GamePort;
bool Running() => IPGlobalProperties.GetIPGlobalProperties().GetActiveUdpListeners().Any(l => l.Port == port);
if (!File.Exists(log) || !Running())
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}

string Read(long from)
{
    using (var stream = new FileStream(log, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
    {
        if (from < 0) from = Math.Max(0, stream.Length - 512 * 1024);
        if (from > stream.Length) from = 0; // the log was started again
        stream.Seek(from, SeekOrigin.Begin);
        using (var reader = new StreamReader(stream, Encoding.UTF8))
            return logArgument.Success ? reader.ReadToEnd() : Unwrap(reader.ReadToEnd());
    }
}
bool Saving(string text)
{
    var started = text.LastIndexOf(" Saving Game\n", StringComparison.Ordinal);
    if (started < 0) started = text.LastIndexOf(" Saving Game\r\n", StringComparison.Ordinal);
    return started >= 0 && text.IndexOf(" Saving Game Finished", started, StringComparison.Ordinal) < 0;
}

// The interval the server runs with (-autoSaveIntervalInSeconds; the server uses at least 60, and 600 without it).
var interval = DefaultInterval;
var argument = Regex.Match(Convert.ToString(ThisService.Commandline) ?? "", "-autoSaveIntervalInSeconds\\s+([0-9.]+)", RegexOptions.IgnoreCase);
if (!argument.Success) interval = 600;
else if (double.TryParse(argument.Groups[1].Value, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var configured))
    interval = configured <= 0 ? 600 : (int)Math.Max(60, configured);

var length = new FileInfo(log).Length;
var tail = Read(-1);
var status = Regex.Matches(tail, "Current/MaxPlayer ([0-9]+)/[0-9]+");
var players = status.Count > 0 ? int.Parse(status[status.Count - 1].Groups[1].Value) : 0;
// The server writes its status every 5 seconds while the world runs; an old line means the world is paused (empty).
var fresh = (DateTime.UtcNow - File.GetLastWriteTimeUtc(log)).TotalSeconds < 30;

int wait;
string reason;
if (Saving(tail)) { wait = 60; reason = "the world is being saved"; }
else if (players > 0 && fresh) { wait = Math.Min(interval + 30, MaxWaitSeconds); reason = players + " player(s) online, waiting for the next autosave"; }
else
{
    ScriptConsole.WriteLine((object)"No players online and no save in progress: the world on disk is up to date.");
    return;
}

ScriptConsole.WriteLine((object)("Stopping after the next save (" + reason + ", at most " + wait + " s)."));
for (var second = 1; second <= wait; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!Running()) { ScriptConsole.WriteLine((object)"The server exited."); return; }
    if (Read(length).Contains(" Saving Game Finished"))
    {
        ScriptConsole.WriteLine((object)("The world was saved after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("No save within " + wait + " s; the panel stops the server now."));

bool InServiceFolder(string path)
{
    try
    {
        var cmp = System.OperatingSystem.IsLinux() ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
        var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');
        var full = Path.GetFullPath(path).TrimEnd('/', '\\');
        if (!full.StartsWith(root + Path.DirectorySeparatorChar, cmp)) return false;
        for (var p = full; p != null && p.Length > root.Length; p = Path.GetDirectoryName(p))
            if (new FileInfo(p).LinkTarget != null) return false;
        return true;
    }
    catch { return false; }
}

// The panel's console copy (.tca/console.log) holds the console rows: colour codes, and long lines broken at the console
// width. Remove the codes and join the rows that fill the whole width with the row after them.
string Unwrap(string raw)
{
    var rows = raw.Split('\n').Select(r => Regex.Replace(r, "\u001b\\[[0-9;?]*[A-Za-z]", "").TrimEnd('\r')).ToArray();
    var width = rows.Length == 0 ? 0 : rows.Max(r => r.Length);
    var joined = new StringBuilder(raw.Length);
    foreach (var row in rows)
    {
        joined.Append(row);
        if (width < 80 || row.Length != width) joined.Append('\n');
    }
    return joined.ToString();
}

//refAssemblies: TCAdmin.Web.Shared.dll, System.Net.NetworkInformation.dll, System.Net.Primitives.dll
using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using System.Text;
using System.Text.RegularExpressions;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Sunkenland has no server query: players find the server through the game's matchmaking service (session list, or the
// Server ID). The query runs on the monitor of the server that hosts the service and reads no network traffic: the
// server is online when its local UDP port is bound and its log says "Server Start Complete". The log also gives the
// Server ID players join with (it changes at every start) and the player count.
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
int port = Convert.ToInt32(Dynamic.Port);
if (port <= 0) port = ThisService.GamePort;

try
{
    IPAddress.TryParse(address, out var ip);
    bool Matches(IPAddress bound)
    {
        if (bound.IsIPv4MappedToIPv6) bound = bound.MapToIPv4();
        return ip == null || bound.Equals(ip) || bound.Equals(IPAddress.Any) || bound.Equals(IPAddress.IPv6Any);
    }
    var listening = IPGlobalProperties.GetIPGlobalProperties().GetActiveUdpListeners().Any(l => l.Port == port && Matches(l.Address));
    string serverId = null, worldName = null, lost = null;
    int players = 0, maxPlayers = ThisService.Slots;
    if (listening)
    {
        // The server log: the -logFile of the command line (Wine), else the copy of the console the panel keeps.
        var logArgument = Regex.Match(Convert.ToString(ThisService.Commandline) ?? "", "-logFile\\s+\"?(?:Z:)?([^\"]+?)\"?(\\s+-|$)", RegexOptions.IgnoreCase);
        var log = logArgument.Success ? logArgument.Groups[1].Value.Trim()
            : Path.Combine((string)ThisService.RootDirectory, ".tca", "console.log");
        if (System.OperatingSystem.IsLinux()) log = log.Replace('\\', '/');
        // The query runs as the monitor (root on Linux) and the command line can be the customer's: read only a file in
        // the service folder with no symbolic link on the way (never a device or a file outside the service).
        if (!InServiceFolder(log)) log = Path.Combine((string)ThisService.RootDirectory, System.OperatingSystem.IsLinux() ? "Logs/server.log" : ".tca/console.log");
        if (InServiceFolder(log) && File.Exists(log))
        {
            // The start-up messages are about 300 KB; while players are online two lines are added every 5 seconds.
            string text;
            using (var stream = new FileStream(log, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
            {
                const int window = 512 * 1024;
                if (stream.Length > window) stream.Seek(-window, SeekOrigin.End);
                using (var reader = new StreamReader(stream, Encoding.UTF8)) text = reader.ReadToEnd();
            }
            if (!logArgument.Success) text = Unwrap(text);
            var started = Regex.Matches(text, "Server Start Complete, Ready for Clients to Join\\. ServerID is '([^']+)'");
            if (started.Count > 0) serverId = started[started.Count - 1].Groups[1].Value;
            // The session ends when the server loses the matchmaking service ("OnShutdown: PhotonCloudTimeout"), but the
            // process keeps running: report it offline so the panel's query monitoring restarts it.
            var shutdown = text.LastIndexOf("OnShutdown: ", StringComparison.Ordinal);
            if (shutdown >= 0 && (started.Count == 0 || shutdown > started[started.Count - 1].Index))
            {
                lost = text.Substring(shutdown + 12, Math.Min(60, text.Length - shutdown - 12)).Split('\n')[0].Trim();
                serverId = null;
            }
            var status = Regex.Matches(text, "WorldName:(.*), ServerID:([^,]+), Region:[^,]*, IsPublic:[^,]*, Current/MaxPlayer ([0-9]+)/([0-9]+)");
            if (status.Count > 0 && lost == null)
            {
                var last = status[status.Count - 1];
                worldName = last.Groups[1].Value;
                serverId = serverId ?? last.Groups[2].Value;
                players = int.Parse(last.Groups[3].Value);
                maxPlayers = int.Parse(last.Groups[4].Value);
            }
        }
    }
    Globals.ReturnValue = listening && serverId != null
        ? new GameQueryResponse
        {
            Success = true,
            Status = "online",
            Protocol = "custom_script",
            Address = address,
            Hostname = string.IsNullOrEmpty(worldName) ? ThisService.Name : worldName,
            Name = string.IsNullOrEmpty(worldName) ? ThisService.Name : worldName,
            GameType = "Sunkenland",
            Map = "Server ID " + serverId,
            NumPlayers = players,
            MaxPlayers = maxPlayers,
            NumSpectators = 0,
            MaxSpectators = 0,
            Retries = 0
        }
        : GameQueryResponse.DefaultOfflineResponse(address, "custom_script",
            lost != null ? "The server lost its matchmaking session (" + lost + ")."
            : listening ? "The server is still starting." : $"Nothing is listening on UDP port {port} of {address}.");
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

bool InServiceFolder(string path)
{
    try
    {
        var linux = System.OperatingSystem.IsLinux();
        var cmp = linux ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
        var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');
        var full = Path.GetFullPath(path).TrimEnd('/', '\\');
        if (!full.StartsWith(root + Path.DirectorySeparatorChar, cmp)) return false;
        for (var p = full; p != null && p.Length > root.Length; p = Path.GetDirectoryName(p))
            if (new FileInfo(p).LinkTarget != null) return false;
        return true;
    }
    catch { return false; }
}

// The panel's console copy (.tca/console.log) holds the console rows: colour codes, and long lines broken at the console
// width. Remove the codes and join the rows that fill the whole width with the row after them.
string Unwrap(string raw)
{
    var rows = raw.Split('\n').Select(r => Regex.Replace(r, "\u001b\\[[0-9;?]*[A-Za-z]", "").TrimEnd('\r')).ToArray();
    var width = rows.Length == 0 ? 0 : rows.Max(r => r.Length);
    var joined = new StringBuilder(raw.Length);
    foreach (var row in rows)
    {
        joined.Append(row);
        if (width < 80 || row.Length != width) joined.Append('\n');
    }
    return joined.ToString();
}
